package ecmaregex

import (
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"testing"
	"unicode"
)

// The golden files are generated by gen/golden.mjs with Node 24 (V8 13.6, Unicode 17), the engine Pi runs on: node gen/golden.mjs, run from this directory. For every pattern of gen/patterns.txt the generator records whether new RegExp(source, "u") and new RegExp(source) compile and, for each input of the shared pool, what RegExp.prototype.test returns. golden_property.json holds the code point ranges V8 matches for every \p{...} expression it accepts, and the expressions it rejects. Pi commit 6d4b7443 (packages/schema/src/shared.ts sharedRegex) is the caller these results stand for.

type goldenRegex struct {
	Node   string   `json:"node"`
	V8     string   `json:"v8"`
	Inputs []string `json:"inputs"`
	Rows   []struct {
		Pattern string  `json:"p"`
		Unicode *string `json:"u"`
		AnnexB  *string `json:"a"`
	} `json:"rows"`
}

type goldenProperty struct {
	Node     string         `json:"node"`
	Unicode  string         `json:"unicode"`
	Sets     [][]rune       `json:"sets"`
	Exprs    map[string]int `json:"exprs"`
	Rejected []string       `json:"rejected"`
}

func readGolden(t *testing.T, name string, into any) {
	t.Helper()
	data, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, into); err != nil {
		t.Fatalf("%s: %v", name, err)
	}
}

func TestGoldenRegex(t *testing.T) {
	var golden goldenRegex
	readGolden(t, "golden_regex.json", &golden)
	if len(golden.Rows) < 400 {
		t.Fatalf("golden has only %d rows", len(golden.Rows))
	}
	for _, row := range golden.Rows {
		t.Run(row.Pattern, func(t *testing.T) {
			compare := func(mode string, compile func(string) (*Regexp, error), want *string) {
				re, err := compile(row.Pattern)
				if want == nil {
					if err == nil {
						t.Errorf("%s: compiled, V8 rejects %q", mode, row.Pattern)
					}
					return
				}
				if err != nil {
					t.Errorf("%s: %q: %v, V8 accepts it", mode, row.Pattern, err)
					return
				}
				for i, input := range golden.Inputs {
					if got, wantMatch := re.MatchString(input), (*want)[i] == '1'; got != wantMatch {
						t.Errorf("%s: %q.test(%q) = %v, V8 says %v", mode, row.Pattern, input, got, wantMatch)
					}
				}
			}
			compare("u", Compile, row.Unicode)
			compare("annexB", CompileAnnexB, row.AnnexB)
			if got, want := Valid(row.Pattern), row.Unicode != nil; got != want {
				t.Errorf("Valid(%q) = %v, want %v", row.Pattern, got, want)
			}
		})
	}
}

// withoutSurrogates returns the sorted, merged ranges of the flat [lo, hi, ...] list with U+D800..U+DFFF removed: Go strings hold no surrogates, so the generator does not probe them either.
func withoutSurrogates(flat []rune) []rune {
	var out []rune
	add := func(lo, hi rune) {
		if lo > hi {
			return
		}
		if n := len(out); n > 0 && out[n-1]+1 >= lo {
			out[n-1] = max(out[n-1], hi)
			return
		}
		out = append(out, lo, hi)
	}
	for i := 0; i < len(flat); i += 2 {
		lo, hi := flat[i], flat[i+1]
		add(lo, min(hi, 0xD7FF))
		add(max(lo, 0xE000), hi)
	}
	return out
}

func flatten(set runeSet) []rune {
	var flat []rune
	for _, r := range set {
		flat = append(flat, r.lo, r.hi)
	}
	return flat
}

func TestGoldenPropertyRanges(t *testing.T) {
	var golden goldenProperty
	readGolden(t, "golden_property.json", &golden)
	if unicode.Version != golden.Unicode+".0" {
		t.Logf("Go tables are Unicode %s, V8's are %s: sets built from Go's tables may differ for characters assigned in between", unicode.Version, golden.Unicode)
	}
	if len(golden.Exprs) < 1500 {
		t.Fatalf("golden has only %d expressions", len(golden.Exprs))
	}
	for expr, id := range golden.Exprs {
		set, ok := propertyRanges(expr)
		if !ok {
			t.Errorf("\\p{%s}: rejected, V8 accepts it", expr)
			continue
		}
		if got, want := withoutSurrogates(flatten(set)), withoutSurrogates(golden.Sets[id]); !slices.Equal(got, want) {
			t.Errorf("\\p{%s}: %s", expr, describeRangeDifference(got, want))
		}
	}
	for _, expr := range golden.Rejected {
		if _, ok := propertyRanges(expr); ok {
			t.Errorf("\\p{%s}: accepted, V8 rejects it", expr)
		}
		for _, source := range []string{`\p{` + expr + `}`, `\P{` + expr + `}`} {
			if Valid(source) {
				t.Errorf("Valid(%q) = true, V8 rejects it", source)
			}
		}
	}
}

// describeRangeDifference names the first code point where two range lists disagree.
func describeRangeDifference(got, want []rune) string {
	in := func(flat []rune, r rune) bool {
		for i := 0; i < len(flat); i += 2 {
			if r >= flat[i] && r <= flat[i+1] {
				return true
			}
		}
		return false
	}
	for r := rune(0); r <= unicode.MaxRune; r++ {
		if in(got, r) != in(want, r) {
			return fmt.Sprintf("first difference at U+%04X: ours %v, V8 %v", r, in(got, r), in(want, r))
		}
	}
	return "ranges differ"
}
